-- 4. Normalise spelling of surviving rows to the canonical name used in the link table.
UPDATE dbo.tblBulkRunSchedule SET Name = N'Hamilton > BOP' WHERE Name = N'Hamilton  > BOP' AND BulkRunScheduleId NOT IN (SELECT BulkRunScheduleId FROM #Retired);
UPDATE dbo.tblBulkRunSchedule SET Name = N'Hamilton > Tauranga afternoon' WHERE Name = N'Hamilton > Tauranga Afternoon' AND BulkRunScheduleId NOT IN (SELECT BulkRunScheduleId FROM #Retired);
UPDATE dbo.tblBulkRunSchedule SET Name = N'IGNORE' WHERE Name = N'ignore' AND BulkRunScheduleId NOT IN (SELECT BulkRunScheduleId FROM #Retired);

-- 5. Safety checks. Each must return 0 rows before @Commit is set to 1.
--    a) every retired id still exists
SELECT r.* FROM #Retired r LEFT JOIN dbo.tblBulkRunSchedule s ON s.BulkRunScheduleId = r.BulkRunScheduleId WHERE s.BulkRunScheduleId IS NULL;
--    b) retired schedule rows that own zone / linehaul rows (NOT compared by this script - the survivor may differ)
--       (in staging these are reported, then removed by step 7 when @RetireDependants = 1)
SELECT z.* FROM dbo.BulkZoneSchedule z JOIN #Retired r ON r.BulkRunScheduleId = z.ScheduleId;
-- SELECT l.* FROM dbo.tblBulkScheduleLinehaul l JOIN #Retired r ON r.BulkRunScheduleId = l.<schedule id column>;
--    c) a link row whose name still matches more than one surviving definition
SELECT l.ScheduleName, COUNT(DISTINCT ISNULL(s.ClientId, -1)) AS Definitions FROM dbo.tblBulkRunScheduleClient l JOIN dbo.tblBulkRunSchedule s ON s.Name = l.ScheduleName
  AND s.BulkRunScheduleId NOT IN (SELECT BulkRunScheduleId FROM #Retired) GROUP BY l.ScheduleName HAVING COUNT(DISTINCT ISNULL(s.ClientId, -1)) > 1;

-- 6. Retire the duplicate client copies.
IF @RetireDependants = 1 DELETE z FROM dbo.BulkZoneSchedule z JOIN #Retired r ON r.BulkRunScheduleId = z.ScheduleId;
DELETE s FROM dbo.tblBulkRunSchedule s JOIN #Retired r ON r.BulkRunScheduleId = s.BulkRunScheduleId;

-- 7. Disable the legacy 1-1 path: surviving client rows lose their ClientId, so the only way a client
--    reaches a schedule is through dbo.tblBulkRunScheduleClient. (Original ClientId values are in dbo.tblBulkRunSchedule_PreRationalise_20260908.)
